//! Bounded framing over the existing native client ABI. No service or provider.
#![forbid(unsafe_op_in_unsafe_fn)]
use std::{
    ffi::{c_char, c_void},
    fmt,
    ptr::{self, NonNull},
    sync::Arc,
    time::{Duration, Instant},
};

// The status codes, frame bounds and call budget of identity.thrift
// (abstraction-ipc CONTRACT.md IPC-E1, IPC-F1, IPC-D1), generated by
// scripts/generate.targets. The crate reads only its constants.
#[allow(dead_code)]
#[path = "../../rs/abstraction/ipc/constants/rec.rs"]
mod constants;

pub const OK: i32 = constants::IPC_OK;
pub const TIMEOUT: i32 = constants::IPC_TIMEOUT;
pub const DISCONNECTED: i32 = constants::IPC_DISCONNECTED;
pub const IO_ERROR: i32 = constants::IPC_IO_ERROR;
pub const INVALID_ARGUMENT: i32 = constants::IPC_INVALID_ARGUMENT;
pub const NO_MEMORY: i32 = constants::IPC_NO_MEMORY;
pub const INTERNAL_ERROR: i32 = constants::IPC_INTERNAL_ERROR;
pub const CANCELLED: i32 = constants::IPC_CANCELLED;
pub const UNTRUSTED: i32 = constants::IPC_UNTRUSTED;
pub const PROOF_UNAVAILABLE: i32 = constants::IPC_PROOF_UNAVAILABLE;
/// Optional ABI-1 native proof of an initial open I/O failure before any write.
/// This status is outside the generated service/wire status records.
pub const OPEN_IO_ERROR: i32 = 10;
/// The budget a call gets when its caller names none (IPC-D1).
pub const DEFAULT_CALL_BUDGET: Duration = Duration::from_millis(constants::IPC_DEFAULT_CALL_BUDGET_MS as u64);
const DEFAULT_MAX_FRAME: usize = constants::IPC_DEFAULT_MAX_FRAME as usize;
const MAX_FRAME: usize = constants::IPC_CLIENT_MAX_FRAME as usize;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ServerExpectation {
    pub principal_kind: u32,
    pub principal: String,
    pub program: String,
}
#[repr(C)]
struct NativeExpectation {
    struct_size: u32,
    version: u32,
    principal_kind: u32,
    reserved: u32,
    principal: *const c_char,
    principal_length: usize,
    program: *const c_char,
    program_length: usize,
}
extern "C" {
    fn oa_ipc_version() -> u32;
    fn oa_ipc_features() -> u32;
    fn oa_ipc_activate_runtime(expected: *const NativeExpectation, timeout_ms: u32,
                               signal: *mut c_void, outcome: *mut i32) -> i32;
    fn oa_ipc_runtime_endpoint(buffer: *mut c_char, capacity: usize, required: *mut usize) -> i32;
    fn oa_ipc_cancellation_create(out: *mut *mut c_void) -> i32;
    fn oa_ipc_cancellation_signal(handle: *mut c_void);
    fn oa_ipc_cancellation_release(handle: *mut c_void);
    fn oa_ipc_select_runtime(timeout_ms: u32, signal: *mut c_void, out: *mut *mut c_void) -> i32;
    fn oa_ipc_selected_server(selection: *const c_void) -> *const NativeExpectation;
    fn oa_ipc_runtime_selection_release(selection: *mut c_void);
    fn oa_ipc_session_call(
        endpoint: *const c_char,
        length: usize,
        timeout_ms: u32,
        signal: *mut c_void,
        server: *const NativeExpectation,
        frame: *const c_void,
        frame_length: usize,
        max_reply: u32,
        flags: u32,
        reply: *mut *mut c_void,
        sent: *mut usize,
    ) -> i32;
    fn oa_ipc_reply_data(reply: *const c_void, length: *mut usize) -> *const u8;
    fn oa_ipc_reply_release(reply: *mut c_void);
}
const CALL_ONE_WAY: u32 = 1;
const CALL_SINGLE_EXCHANGE: u32 = 2;
const FEATURE_SINGLE_EXCHANGE: u32 = 4;
const CALL_REPORT_OPEN_FAILURE: u32 = 4;
const FEATURE_OPEN_FAILURE: u32 = 8;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    pub status: i32,
    /// Native-confirmed request payload bytes for a framed call. Zero alone
    /// does not establish that an empty request header was never delivered.
    pub transferred: usize,
    pub message: &'static str,
}
impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "{} (status {}, confirmed prefix {})",
            self.message, self.status, self.transferred
        )
    }
}
impl std::error::Error for Error {}
fn error(status: i32, message: &'static str) -> Error {
    Error {
        status,
        message,
        transferred: 0,
    }
}
fn version() -> Result<(), Error> {
    // No pointers or ownership cross this ABI query.
    if unsafe { oa_ipc_version() } != 1 {
        Err(error(INVALID_ARGUMENT, "unsupported IPC ABI"))
    } else {
        Ok(())
    }
}

pub fn runtime_endpoint() -> Result<String, Error> {
    version()?;
    let mut required = 0usize;
    // Query writes only our live usize. Native code owns no returned allocation.
    let mut status = unsafe { oa_ipc_runtime_endpoint(ptr::null_mut(), 0, &mut required) };
    for _ in 0..3 {
        if status != OK {
            return Err(error(status, "bootstrap query failed"));
        }
        if !(2..=65536).contains(&required) {
            return Err(error(INVALID_ARGUMENT, "bootstrap size invalid"));
        }
        let mut bytes = vec![0u8; required];
        // Buffer and required remain exclusively borrowed throughout the call.
        status = unsafe {
            oa_ipc_runtime_endpoint(bytes.as_mut_ptr().cast(), bytes.len(), &mut required)
        };
        if status == INVALID_ARGUMENT && required > bytes.len() {
            status = OK;
            continue;
        }
        if status != OK {
            return Err(error(status, "bootstrap copy failed"));
        }
        if required < 2 || required > bytes.len() || bytes[required - 1] != 0 {
            return Err(error(INTERNAL_ERROR, "invalid bootstrap result"));
        }
        bytes.truncate(required - 1);
        return String::from_utf8(bytes)
            .map_err(|_| error(INVALID_ARGUMENT, "bootstrap is not UTF-8"));
    }
    Err(error(INVALID_ARGUMENT, "bootstrap changed repeatedly"))
}

/// Milliseconds left before `deadline`, rounded up, or `TIMEOUT` once it passed.
fn budget(deadline: Instant, message: &'static str) -> Result<u32, Error> {
    let remaining = deadline.saturating_duration_since(Instant::now());
    if remaining.is_zero() {
        return Err(error(TIMEOUT, message));
    }
    // Whole milliseconds, a started one counted.
    Ok(remaining.as_nanos().div_ceil(1_000_000).min(u32::MAX as u128) as u32)
}

/// Selects the installed runtime's identity through the shared native selector,
/// without connecting to it or starting it. Windows reads the registered
/// installation of the current account; Linux reads the loaded user runtime unit.
/// No installation, or an ambiguous one, is `UNTRUSTED`; a platform without the
/// required facilities is `PROOF_UNAVAILABLE`. The endpoint override variable
/// never supplies this identity. Pass the result to
/// `FrameTransport::with_server_expectation` for every connection that must
/// reach that runtime.
pub fn select_runtime(
    deadline: Instant,
    cancellation: Option<&Cancellation>,
) -> Result<ServerExpectation, Error> {
    version()?;
    let millis = budget(deadline, "runtime selection deadline expired")?;
    let signal = cancellation
        .map(|s| s.0 .0.as_ptr())
        .unwrap_or(ptr::null_mut());
    let mut raw = ptr::null_mut();
    // The borrowed signal outlives this synchronous call; the selection is
    // released below on every path after its strings are copied.
    let status = unsafe { oa_ipc_select_runtime(millis, signal, &mut raw) };
    if status != OK {
        return Err(error(status, "installed runtime selection failed"));
    }
    let selection = NonNull::new(raw)
        .ok_or_else(|| error(INTERNAL_ERROR, "native runtime selection absent"))?;
    struct Selection(NonNull<c_void>);
    impl Drop for Selection {
        fn drop(&mut self) {
            unsafe { oa_ipc_runtime_selection_release(self.0.as_ptr()) }
        }
    }
    let selection = Selection(selection);
    // The expectation and its strings belong to the selection until release.
    let server = unsafe { oa_ipc_selected_server(selection.0.as_ptr()).as_ref() }
        .ok_or_else(|| error(INTERNAL_ERROR, "native runtime identity absent"))?;
    let text = |pointer: *const c_char, length: usize| -> Result<String, Error> {
        if pointer.is_null() || !(1..=65536).contains(&length) {
            return Err(error(INTERNAL_ERROR, "invalid native runtime identity"));
        }
        // Length-bounded span inside the live selection snapshot.
        let bytes = unsafe { std::slice::from_raw_parts(pointer.cast::<u8>(), length) };
        if bytes.contains(&0) {
            return Err(error(INTERNAL_ERROR, "invalid native runtime identity"));
        }
        String::from_utf8(bytes.to_vec())
            .map_err(|_| error(INVALID_ARGUMENT, "runtime identity is not UTF-8"))
    };
    if server.struct_size as usize != std::mem::size_of::<NativeExpectation>()
        || server.version != 1
        || server.reserved != 0
        || ![1, 2].contains(&server.principal_kind)
    {
        return Err(error(INTERNAL_ERROR, "invalid native runtime identity"));
    }
    let selected = ServerExpectation {
        principal_kind: server.principal_kind,
        principal: text(server.principal, server.principal_length)?,
        program: text(server.program, server.program_length)?,
    };
    drop(selection);
    if Instant::now() >= deadline {
        return Err(error(TIMEOUT, "runtime selection deadline expired"));
    }
    Ok(selected)
}

/// Outcome of the bounded native activation request. Readiness is checked by a verified call.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(i32)]
pub enum ActivationOutcome {
    None = 0,
    RequestCompleted = 1,
    EndpointPresent = 2,
    UpgradeInProgress = 3,
    Refused = 4,
}

/// Requires a paired native library exporting the runtime activation extension.
pub fn activate_runtime(expected: &ServerExpectation, deadline: Instant,
                        cancellation: Option<&Cancellation>) -> Result<ActivationOutcome, Error> {
    version()?;
    let millis = budget(deadline, "runtime activation deadline expired")?;
    if ![1, 2].contains(&expected.principal_kind) || expected.principal.is_empty()
        || expected.program.is_empty() || expected.principal.contains('\0') || expected.program.contains('\0') {
        return Err(error(INVALID_ARGUMENT, "invalid server expectation"));
    }
    if unsafe { oa_ipc_features() } & 2 == 0 {
        return Err(error(PROOF_UNAVAILABLE, "native runtime activation unavailable"));
    }
    let native = NativeExpectation { struct_size: std::mem::size_of::<NativeExpectation>() as u32,
        version: 1, principal_kind: expected.principal_kind, reserved: 0,
        principal: expected.principal.as_ptr().cast(), principal_length: expected.principal.len(),
        program: expected.program.as_ptr().cast(), program_length: expected.program.len() };
    let signal = cancellation.map(|s| s.0 .0.as_ptr()).unwrap_or(ptr::null_mut());
    let mut outcome = 0;
    // Expected strings and the borrowed cancellation remain live for the full call.
    let status = unsafe { oa_ipc_activate_runtime(&native, millis, signal, &mut outcome) };
    if status != OK { return Err(error(status, "installed runtime activation failed")); }
    budget(deadline, "runtime activation deadline expired")?;
    match outcome {
        1 => Ok(ActivationOutcome::RequestCompleted),
        2 => Ok(ActivationOutcome::EndpointPresent),
        3 => Ok(ActivationOutcome::UpgradeInProgress),
        4 => Ok(ActivationOutcome::Refused),
        _ => Err(error(INTERNAL_ERROR, "invalid native activation outcome")),
    }
}

struct Signal(NonNull<c_void>);
// The ABI explicitly permits concurrent signal calls. Arc keeps release after
// the last borrowed open/signal call; there is no public raw handle access.
unsafe impl Send for Signal {}
unsafe impl Sync for Signal {}
impl Drop for Signal {
    fn drop(&mut self) {
        unsafe { oa_ipc_cancellation_release(self.0.as_ptr()) }
    }
}
#[derive(Clone)]
pub struct Cancellation(Arc<Signal>);
impl Cancellation {
    pub fn new() -> Result<Self, Error> {
        version()?;
        let mut raw = ptr::null_mut();
        let status = unsafe { oa_ipc_cancellation_create(&mut raw) };
        if status != OK {
            return Err(error(status, "cancellation creation failed"));
        }
        let pointer =
            NonNull::new(raw).ok_or_else(|| error(INTERNAL_ERROR, "native null signal"))?;
        Ok(Self(Arc::new(Signal(pointer))))
    }
    pub fn signal(&self) {
        unsafe { oa_ipc_cancellation_signal(self.0 .0.as_ptr()) }
    }
}

#[derive(Clone)]
pub struct FrameTransport {
    endpoint: String,
    timeout: Duration,
    deadline: Option<Instant>,
    cancellation: Option<Cancellation>,
    limit: usize,
    server: Option<ServerExpectation>,
    sessions: bool,
}
impl FrameTransport {
    pub fn new(endpoint: impl Into<String>, timeout: Duration) -> Result<Self, Error> {
        let endpoint = endpoint.into();
        if endpoint.is_empty()
            || endpoint.as_bytes().contains(&0)
            || timeout.as_millis() > u32::MAX as u128
        {
            return Err(error(INVALID_ARGUMENT, "invalid endpoint or timeout"));
        }
        Ok(Self {
            endpoint,
            timeout,
            deadline: None,
            cancellation: None,
            limit: DEFAULT_MAX_FRAME,
            server: None,
            sessions: false,
        })
    }
    /// Keep verified connections for later calls in the shared library's
    /// session pool (listen/FRAMING.md "Sessions"). Ask only where the server
    /// answers or closes an oversized header.
    pub fn with_sessions(mut self, sessions: bool) -> Self {
        self.sessions = sessions;
        self
    }
    pub fn with_server_expectation(mut self, server: ServerExpectation) -> Result<Self, Error> {
        if ![1, 2].contains(&server.principal_kind)
            || server.principal.is_empty()
            || server.program.is_empty()
            || server.principal.as_bytes().contains(&0)
            || server.program.as_bytes().contains(&0)
        {
            return Err(error(INVALID_ARGUMENT, "invalid server expectation"));
        }
        self.server = Some(server);
        Ok(self)
    }
    pub fn with_deadline(mut self, deadline: Instant) -> Self {
        self.deadline = Some(deadline);
        self
    }
    pub fn with_cancellation(mut self, signal: Cancellation) -> Self {
        self.cancellation = Some(signal);
        self
    }
    pub fn with_limit(mut self, limit: usize) -> Result<Self, Error> {
        if limit == 0 || limit > MAX_FRAME {
            return Err(error(INVALID_ARGUMENT, "frame limit must be from 1 to the client maximum"));
        }
        self.limit = limit;
        Ok(self)
    }
    fn millis(&self) -> Result<u32, Error> {
        let remaining = self
            .deadline
            .map(|d| d.saturating_duration_since(Instant::now()))
            .unwrap_or(self.timeout);
        if remaining.is_zero() {
            return Err(error(TIMEOUT, "call deadline expired"));
        }
        // Whole milliseconds, a started one counted.
        Ok(remaining.as_nanos().div_ceil(1_000_000).min(u32::MAX as u128) as u32)
    }
    fn call_flags(&self, features: u32, one_way: bool) -> Result<u32, Error> {
        let message = self.endpoint.starts_with("xpc:");
        if message && features & 1 == 0 {
            return Err(error(PROOF_UNAVAILABLE, "native XPC transport unavailable"));
        }
        let single = !self.sessions && !message;
        if single && features & FEATURE_SINGLE_EXCHANGE == 0 {
            return Err(error(PROOF_UNAVAILABLE, "native single-exchange transport unavailable"));
        }
        Ok((if one_way { CALL_ONE_WAY } else { 0 }) |
           (if single { CALL_SINGLE_EXCHANGE } else { 0 }) |
           (if !message && features & FEATURE_OPEN_FAILURE != 0 { CALL_REPORT_OPEN_FAILURE } else { 0 }))
    }
    fn session_call(&self, frame: &[u8], one_way: bool) -> Result<Vec<u8>, Error> {
        version()?;
        if frame.len() > self.limit {
            return Err(error(INVALID_ARGUMENT, "outbound frame too large"));
        }
        let flags = self.call_flags(unsafe { oa_ipc_features() }, one_way)?;
        let millis = self.millis()?;
        let signal = self
            .cancellation
            .as_ref()
            .map(|s| s.0 .0.as_ptr())
            .unwrap_or(ptr::null_mut());
        let expected = self.server.as_ref().map(|server| NativeExpectation {
            struct_size: std::mem::size_of::<NativeExpectation>() as u32,
            version: 1,
            principal_kind: server.principal_kind,
            reserved: 0,
            principal: server.principal.as_ptr().cast(),
            principal_length: server.principal.len(),
            program: server.program.as_ptr().cast(),
            program_length: server.program.len(),
        });
        let mut reply = ptr::null_mut();
        let mut sent = 0usize;
        // Every span is borrowed for this synchronous call; the reply is owned
        // by the native library until released below.
        let status = unsafe {
            oa_ipc_session_call(
                self.endpoint.as_ptr().cast(),
                self.endpoint.len(),
                millis,
                signal,
                expected
                    .as_ref()
                    .map_or(ptr::null(), |e| e as *const NativeExpectation),
                frame.as_ptr().cast(),
                frame.len(),
                self.limit as u32,
                flags,
                &mut reply,
                &mut sent,
            )
        };
        let bytes = if status == OK && !reply.is_null() {
            let mut length = 0usize;
            let data = unsafe { oa_ipc_reply_data(reply, &mut length) };
            if data.is_null() || length == 0 {
                Vec::new()
            } else {
                unsafe { std::slice::from_raw_parts(data, length) }.to_vec()
            }
        } else {
            Vec::new()
        };
        if !reply.is_null() {
            unsafe { oa_ipc_reply_release(reply) }
        }
        if status != OK {
            return Err(Error {
                status,
                transferred: sent,
                message: if status == OPEN_IO_ERROR { "IPC open failed" } else {
                    "frame exchange failed; acceptance may be unknown"
                },
            });
        }
        Ok(bytes)
    }
    pub fn exchange_frame(&self, frame: &[u8]) -> Result<Vec<u8>, Error> {
        self.session_call(frame, false)
    }
    pub fn write_frame(&self, frame: &[u8]) -> Result<(), Error> {
        self.session_call(frame, true).map(|_| ())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn native_feature_admission_preserves_single_session_and_xpc_modes() {
        let ordinary = FrameTransport::new("unused", Duration::from_secs(1)).unwrap();
        for features in [0, 1, 2, 3] {
            assert_eq!(ordinary.call_flags(features, false).unwrap_err().status, PROOF_UNAVAILABLE);
        }
        assert_eq!(ordinary.call_flags(4, false).unwrap(), 2);
        assert_eq!(ordinary.call_flags(4, true).unwrap(), 3);
        assert_eq!(ordinary.call_flags(12, false).unwrap(), 6);
        assert_eq!(ordinary.call_flags(12, true).unwrap(), 7);
        let session = ordinary.with_sessions(true);
        assert_eq!(session.call_flags(0, false).unwrap(), 0);
        assert_eq!(session.call_flags(0, true).unwrap(), 1);
        assert_eq!(session.call_flags(8, false).unwrap(), 4);
        let message = FrameTransport::new("xpc:fixture", Duration::from_secs(1)).unwrap();
        assert_eq!(message.call_flags(4, false).unwrap_err().status, PROOF_UNAVAILABLE);
        assert_eq!(message.call_flags(1, false).unwrap(), 0);
        assert_eq!(message.call_flags(1, true).unwrap(), 1);
        assert_eq!(message.call_flags(9, false).unwrap(), 0);
    }
    #[cfg(any(windows, target_os = "linux"))]
    #[test]
    fn native_single_exchange_preserves_empty_binary_and_unknown_empty_failure() {
        for payload in [b"".as_slice(), b"\0\xff\n".as_slice()] {
            let (endpoint, worker) = echo_once();
            let transport = FrameTransport::new(endpoint, Duration::from_secs(2)).unwrap();
            assert_eq!(transport.exchange_frame(payload).unwrap(), payload);
            worker.join().unwrap();
        }
        let (endpoint, worker) = echo_once();
        let transport = FrameTransport::new(endpoint, Duration::from_secs(2)).unwrap();
        let failure = transport.write_frame(b"").unwrap_err();
        assert_eq!(failure.status, IO_ERROR);
        assert_eq!(failure.transferred, 0);
        assert!(failure.message.contains("acceptance may be unknown"));
        worker.join().unwrap();
    }
    #[cfg(any(windows, target_os = "linux"))]
    #[test]
    fn native_missing_endpoint_projects_open_failure() {
        let endpoint = if cfg!(windows) {
            format!(r"\\.\pipe\oa-rust-open-missing-{}", std::process::id())
        } else {
            std::env::temp_dir().join(format!("oa-rust-open-missing-{}", std::process::id()))
                .to_str().unwrap().to_owned()
        };
        for payload in [b"".as_slice(), b"request".as_slice()] {
            let failure = FrameTransport::new(&endpoint, Duration::from_secs(1)).unwrap()
                .exchange_frame(payload).unwrap_err();
            assert_eq!(failure.status, OPEN_IO_ERROR);
            assert_eq!(failure.transferred, 0);
        }
    }
    #[test]
    fn activation_refuses_invalid_expectations_and_expired_budget_before_request() {
        let expected=ServerExpectation {principal_kind:0,principal:"fixture".into(),program:"/fixture".into()};
        assert_eq!(activate_runtime(&expected,Instant::now()+Duration::from_secs(1),None).unwrap_err().status,INVALID_ARGUMENT);
        assert_eq!(activate_runtime(&expected,Instant::now(),None).unwrap_err().status,TIMEOUT);
    }
    #[test]
    fn activation_relative_program_reaches_native_validation_without_selection() {
        // ServerGuard::valid_input rejects this program before activate_runtime
        // can select an installation, inspect a profile or start a child.
        let principal="fixture-user";
        let program="relative";
        let native=NativeExpectation {struct_size:std::mem::size_of::<NativeExpectation>() as u32,
            version:1,principal_kind:if cfg!(windows) {1} else {2},reserved:0,
            principal:principal.as_ptr().cast(),principal_length:principal.len(),
            program:program.as_ptr().cast(),program_length:program.len()};
        let mut outcome=123;
        let status=unsafe {oa_ipc_activate_runtime(&native,100,ptr::null_mut(),&mut outcome)};
        assert_eq!(status,INVALID_ARGUMENT);
        assert_eq!(outcome,ActivationOutcome::None as i32);
        let expected=ServerExpectation {principal_kind:native.principal_kind,
            principal:principal.into(),program:program.into()};
        assert_eq!(activate_runtime(&expected,Instant::now()+Duration::from_secs(1),None)
            .unwrap_err().status,INVALID_ARGUMENT);
    }
    #[test]
    fn scopes_retain_server_evidence() {
        let server = ServerExpectation {
            principal_kind: 2,
            principal: "123".into(),
            program: "/installed/runtime".into(),
        };
        let transport = FrameTransport::new("unused", Duration::from_secs(1))
            .unwrap()
            .with_server_expectation(server.clone())
            .unwrap();
        let scoped = transport.clone().with_deadline(Instant::now());
        assert_eq!(scoped.server, Some(server.clone()));
        assert_eq!(
            transport.clone().with_deadline(Instant::now()).server,
            Some(server.clone())
        );
        assert_eq!(
            transport
                .with_cancellation(Cancellation::new().unwrap())
                .server,
            Some(server)
        );
    }
    #[cfg(target_os = "linux")]
    #[test]
    fn native_verified_server_refuses_before_payload() {
        use std::io::{Read, Write};
        use std::os::unix::net::UnixListener;
        let uid = std::fs::read_to_string("/proc/self/status")
            .unwrap()
            .lines()
            .find(|l| l.starts_with("Uid:"))
            .unwrap()
            .split_whitespace()
            .nth(1)
            .unwrap()
            .to_owned();
        for wrong in [false, true] {
            let path = std::env::temp_dir().join(format!(
                "oa-rust-trust-{}-{}",
                std::process::id(),
                wrong
            ));
            let listener = UnixListener::bind(&path).unwrap();
            let worker = std::thread::spawn(move || {
                let (mut peer, _) = listener.accept().unwrap();
                peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
                let mut header = [0u8; 4];
                if wrong {
                    let mut b = [0u8; 1];
                    assert_eq!(peer.read(&mut b).unwrap(), 0);
                } else {
                    peer.read_exact(&mut header).unwrap();
                    let mut b = vec![0u8; u32::from_be_bytes(header) as usize];
                    peer.read_exact(&mut b).unwrap();
                    peer.write_all(&header).unwrap();
                    peer.write_all(&b).unwrap();
                }
            });
            let expected = ServerExpectation {
                principal_kind: 2,
                principal: uid.clone(),
                program: if wrong {
                    "/untrusted/other".into()
                } else {
                    std::env::current_exe().unwrap().to_str().unwrap().into()
                },
            };
            let result = FrameTransport::new(path.to_str().unwrap(), Duration::from_secs(1))
                .unwrap()
                .with_server_expectation(expected)
                .unwrap()
                .exchange_frame(b"private");
            if wrong {
                assert_eq!(result.unwrap_err().status, UNTRUSTED);
            } else {
                assert_eq!(result.unwrap(), b"private");
            }
            worker.join().unwrap();
            std::fs::remove_file(path).unwrap();
        }
    }
    /// PT-5a through the C ABI: the server image (this test binary) is
    /// matched by file identity. Another name for it keeps the check; a
    /// different file at a name the expectation uses fails it.
    #[cfg(any(windows, target_os = "linux"))]
    #[test]
    fn server_image_is_matched_by_file_identity() {
        let image = std::env::current_exe().unwrap();
        let folder = image
            .parent()
            .unwrap()
            .join(format!("oa-rust-identity-{}", std::process::id()));
        std::fs::create_dir_all(&folder).unwrap();
        let ext = if cfg!(windows) { ".exe" } else { "" };
        let link = folder.join(format!("linked{ext}"));
        let moved = folder.join(format!("moved{ext}"));
        std::fs::hard_link(&image, &link).unwrap();
        let first = identity_call(link.to_str().unwrap());
        std::fs::rename(&link, &moved).unwrap();
        let second = identity_call(moved.to_str().unwrap());
        std::fs::copy(&image, &link).unwrap();
        let third = identity_call(link.to_str().unwrap());
        std::fs::remove_dir_all(&folder).unwrap();
        assert_eq!(first.unwrap(), b"private");
        assert_eq!(second.unwrap(), b"private");
        assert_eq!(third.unwrap_err().status, UNTRUSTED);
    }
    #[cfg(any(windows, target_os = "linux"))]
    fn identity_call(program: &str) -> Result<Vec<u8>, Error> {
        let (endpoint, worker) = echo_once();
        let expected = ServerExpectation {
            principal_kind: if cfg!(windows) { 1 } else { 2 },
            principal: own_principal(),
            program: program.into(),
        };
        let result = FrameTransport::new(&endpoint, Duration::from_secs(2))
            .unwrap()
            .with_server_expectation(expected)
            .unwrap()
            .exchange_frame(b"private");
        worker.join().unwrap();
        result
    }
    #[cfg(windows)]
    fn own_principal() -> String {
        let out = std::process::Command::new("whoami")
            .args(["/user", "/fo", "csv", "/nh"])
            .output()
            .unwrap();
        let text = String::from_utf8(out.stdout).unwrap();
        text.trim()
            .rsplit(',')
            .next()
            .unwrap()
            .trim_matches('"')
            .to_owned()
    }
    #[cfg(target_os = "linux")]
    fn own_principal() -> String {
        std::fs::read_to_string("/proc/self/status")
            .unwrap()
            .lines()
            .find(|l| l.starts_with("Uid:"))
            .unwrap()
            .split_whitespace()
            .nth(1)
            .unwrap()
            .to_owned()
    }
    #[cfg(windows)]
    fn echo_once() -> (String, std::thread::JoinHandle<()>) {
        type Handle = *mut std::ffi::c_void;
        extern "system" {
            fn CreateNamedPipeW(
                n: *const u16,
                o: u32,
                p: u32,
                m: u32,
                ob: u32,
                ib: u32,
                t: u32,
                s: *mut std::ffi::c_void,
            ) -> Handle;
            fn ConnectNamedPipe(h: Handle, o: *mut std::ffi::c_void) -> i32;
            fn ReadFile(
                h: Handle,
                b: *mut u8,
                n: u32,
                r: *mut u32,
                o: *mut std::ffi::c_void,
            ) -> i32;
            fn WriteFile(
                h: Handle,
                b: *const u8,
                n: u32,
                w: *mut u32,
                o: *mut std::ffi::c_void,
            ) -> i32;
            fn DisconnectNamedPipe(h: Handle) -> i32;
            fn CloseHandle(h: Handle) -> i32;
        }
        let name = format!(
            r"\\.\pipe\oa-rust-identity-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        );
        let wide: Vec<u16> = name.encode_utf16().chain(Some(0)).collect();
        let pipe = unsafe {
            CreateNamedPipeW(wide.as_ptr(), 3, 0, 1, 4096, 4096, 0, std::ptr::null_mut())
        };
        assert!(!pipe.is_null() && pipe as isize != -1);
        let pipe = pipe as usize;
        let worker = std::thread::spawn(move || unsafe {
            let pipe = pipe as Handle;
            let null = std::ptr::null_mut();
            ConnectNamedPipe(pipe, null);
            let mut buf = [0u8; 4096];
            let mut n = 0u32;
            while ReadFile(pipe, buf.as_mut_ptr(), buf.len() as u32, &mut n, null) != 0 && n > 0 {
                let mut w = 0u32;
                WriteFile(pipe, buf.as_ptr(), n, &mut w, null);
            }
            DisconnectNamedPipe(pipe);
            CloseHandle(pipe);
        });
        (name, worker)
    }
    #[cfg(target_os = "linux")]
    fn echo_once() -> (String, std::thread::JoinHandle<()>) {
        use std::io::{Read, Write};
        let path = std::env::temp_dir().join(format!(
            "oa-rust-identity-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let listener = std::os::unix::net::UnixListener::bind(&path).unwrap();
        let endpoint = path.to_str().unwrap().to_owned();
        let worker = std::thread::spawn(move || {
            if let Ok((mut peer, _)) = listener.accept() {
                let mut buf = [0u8; 4096];
                while let Ok(n) = peer.read(&mut buf) {
                    if n == 0 || peer.write_all(&buf[..n]).is_err() {
                        break;
                    }
                }
            }
            let _ = std::fs::remove_file(path);
        });
        (endpoint, worker)
    }
    #[test]
    fn invalid_native_expectation_does_not_open() {
        let server = ServerExpectation {
            principal_kind: if cfg!(windows) { 1 } else { 2 },
            principal: "123".into(),
            program: "relative".into(),
        };
        let result = FrameTransport::new("unused", Duration::from_secs(1))
            .unwrap()
            .with_server_expectation(server)
            .unwrap()
            .exchange_frame(b"private");
        assert_eq!(result.unwrap_err().status, INVALID_ARGUMENT);
    }
    #[test]
    fn invalid_before_open() {
        assert!(FrameTransport::new("bad\0endpoint", Duration::from_secs(1)).is_err());
        let t = FrameTransport::new("unused", Duration::ZERO).unwrap();
        assert_eq!(t.exchange_frame(b"x").unwrap_err().status, TIMEOUT);
        assert_eq!(
            t.with_limit(1)
                .unwrap()
                .exchange_frame(b"xx")
                .unwrap_err()
                .status,
            INVALID_ARGUMENT
        );
    }
    #[test]
    fn selection_answers_with_an_identity_or_a_trust_refusal() {
        assert_eq!(
            select_runtime(Instant::now(), None).unwrap_err().status,
            TIMEOUT
        );
        let signal = Cancellation::new().unwrap();
        signal.signal();
        let cancelled = select_runtime(Instant::now() + Duration::from_secs(1), Some(&signal));
        assert!(
            matches!(&cancelled, Err(e) if e.status == CANCELLED),
            "{cancelled:?}"
        );
        // This host may or may not hold an installation; either answer is typed.
        match select_runtime(Instant::now() + Duration::from_secs(5), None) {
            Ok(server) => {
                assert_eq!(server.principal_kind, if cfg!(windows) { 1 } else { 2 });
                assert!(std::path::Path::new(&server.program).is_absolute());
            }
            Err(e) => assert!([UNTRUSTED, PROOF_UNAVAILABLE].contains(&e.status), "{e}"),
        }
    }
    #[test]
    fn cancelled_before_open() {
        let signal = Cancellation::new().unwrap();
        signal.signal();
        let t = FrameTransport::new("unused", Duration::from_secs(1))
            .unwrap()
            .with_cancellation(signal);
        assert_eq!(t.exchange_frame(b"x").unwrap_err().status, CANCELLED);
    }
}

// All generated service protocols share this transport implementation.
impl abstraction_frame::FrameTransport for FrameTransport {
    type Error = Error;
    fn write_frame(&self, frame: &[u8]) -> Result<(), Self::Error> {
        FrameTransport::write_frame(self, frame)
    }
    fn exchange_frame(&self, frame: &[u8]) -> Result<Vec<u8>, Self::Error> {
        FrameTransport::exchange_frame(self, frame)
    }
}
